/**
 * Delivery pump: dequeue → skip duplicates → claim → deliver → ack + record,
 * or requeue with backoff on failure.
 *
 * Guarantee mechanics:
 *
 * - Effectively-once: an id is claimed the moment its single delivery attempt
 *   starts, because the downstream may accept the message even when the attempt
 *   is reported as failed. The claim lives in a pump-local set that never
 *   expires (the sliding dedup window would), so a retry can never reopen a
 *   delivered or attempted id. A failed message is therefore never attempted
 *   again: it is requeued with backoff, and when it comes back due, the claim
 *   suppresses re-delivery and the message is abandoned with a failure record.
 *   sink.emit only records a confirmed delivery, once per id.
 *
 * - Per-key ordering: a failed message is requeued at the head of the queue —
 *   its original position — and a retry that is not yet due blocks the head of
 *   the queue instead of being skipped, so no later message (same key or
 *   otherwise) can be delivered before it resolves. Successors of the same key
 *   only proceed after the earlier message has been delivered or abandoned.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  // Ids for which a delivery attempt has started. Never expires: window-based
  // dedup alone cannot guarantee effectively-once across a long backoff.
  const claimed = new Set()
  return {
    run(steps = Infinity) {
      for (let i = 0; i < steps; i++) {
        const message = queue.dequeue()
        if (message === null) break
        if (message.retryAt !== undefined && clock.now() < message.retryAt) {
          // Not due yet. Put it back at the head and stop: delivering anything
          // behind it would let a later message (same key included) overtake
          // this one, breaking per-key ordering. Wait for the clock to advance.
          queue.requeue(message)
          break
        }
        const alreadyClaimed = claimed.has(message.id)
        if (alreadyClaimed || dedup.isDuplicate(message.id, clock.now())) {
          queue.ack(message.id)
          if (alreadyClaimed) {
            // Retry of an already-attempted message: the earlier attempt may
            // have been accepted downstream, so re-delivering could duplicate.
            // Abandon it with a failure record instead of a second delivery.
            sink.failed(message)
          }
          continue
        }
        // Claim before the attempt: from this moment the id counts as spent.
        claimed.add(message.id)
        dedup.record(message.id, clock.now())
        let ok
        try {
          ok = processMessage(message)
        } catch {
          // A throw is a failed attempt like any other (and may have happened
          // after the downstream accepted); route it through the failure path
          // instead of losing the message that is already out of the queue.
          ok = false
        }
        if (!ok) {
          message.attempts += 1
          if (message.attempts >= maxAttempts) {
            queue.ack(message.id)
            sink.failed(message)
            continue
          }
          message.retryAt = clock.now() + retryWithBackoff(clock).delayFor(message.attempts)
          queue.requeue(message)
          continue
        }
        sink.emit(message)
        queue.ack(message.id)
      }
    },
  }
}

// Scratch verification harness for the two authoritative guarantees under
// failure + retry paths. Not part of the test suite; deleted after use.
import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink } from './src/index.js'

function makeClock() {
  let t = 0
  return { now: () => t, advance: (ms) => { t += ms } }
}

// G1: a delivery attempt that is accepted downstream but reported as failed
// must never lead to a second downstream call or a second sink delivery.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = makeClock()
  const downstream = []
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 50 }), sink, clock,
    processMessage: (m) => { downstream.push(m.id); return false }, // accepted, then "fails"
  })
  pump.run(10)
  clock.advance(1000)
  pump.run(10)
  clock.advance(1000)
  pump.run(10)
  assert.equal(downstream.filter((id) => id === 'm1').length, 1, 'G1: downstream hit exactly once')
  assert.deepEqual(sink.deliveredIds(), [], 'G1: unconfirmed attempt not recorded as delivered')
  assert.deepEqual(sink.failedIds(), ['m1'], 'G1: abandoned message reported failed')
  assert.equal(sink.hasDuplicate(), false, 'G1: no duplicate in delivered stream')
}

// G1b: dedup window far shorter than the backoff — window expiry must not
// reopen a claimed id.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = makeClock()
  const downstream = []
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 10 }), sink, clock,
    processMessage: (m) => { downstream.push(m.id); return false },
  })
  pump.run(10)              // fails at t=0, retryAt=100, window is 10ms
  clock.advance(5000)       // way past both the window and the backoff
  pump.run(10)
  assert.equal(downstream.length, 1, 'G1b: no re-attempt after window expiry')
  assert.deepEqual(sink.failedIds(), ['m1'])
}

// G1c: a thrown attempt must not lose the message nor re-deliver it.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = makeClock()
  const downstream = []
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 1000 }), sink, clock,
    processMessage: (m) => { downstream.push(m.id); throw new Error('ack lost') },
  })
  pump.run(10)
  clock.advance(1000)
  pump.run(10)
  assert.equal(downstream.length, 1, 'G1c: downstream hit exactly once despite throw')
  assert.deepEqual(sink.failedIds(), ['m1'], 'G1c: message not lost, reported failed')
  assert.deepEqual(queue.pending(), [], 'G1c: queue drained')
}

// G2: same-key ordering across retries — a later same-key message must not be
// delivered while the earlier one still waits, and never after it resolves.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = makeClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  queue.enqueue({ id: 'm3', key: 'K2', payload: 3 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 1000 }), sink, clock,
    processMessage: (m) => (m.id === 'm1' ? false : true), // m1 fails forever
  })
  pump.run(10) // m1 fails, requeued at head; nothing may overtake it
  assert.deepEqual(sink.deliveredIds(), [], 'G2: nothing delivered while m1 waits')
  clock.advance(1000)
  pump.run(10) // m1 abandoned, then m2 and m3 proceed in queue order
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.deepEqual(sink.deliveredIds(), ['m2', 'm3'], 'G2: successors proceed after resolution, in order')
}

// G2b: no same-key overtake even with a healthy downstream and interleaved keys.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = makeClock()
  for (const m of [['a', 'K1'], ['b', 'K2'], ['c', 'K1'], ['d', 'K2']]) {
    queue.enqueue({ id: m[0], key: m[1], payload: 0 })
  }
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 1000 }), sink, clock,
    processMessage: (m) => (m.id === 'b' ? false : true), // b fails once... forever
  })
  pump.run(10)
  clock.advance(1000)
  pump.run(10)
  const d = sink.deliveredIds()
  assert.equal(d.indexOf('a') < d.indexOf('c'), true, 'G2b: K1 order a before c')
  assert.equal(d.indexOf('b'), -1, 'G2b: b abandoned, never delivered')
  assert.deepEqual(sink.failedIds(), ['b'])
}

// G3: producer replay of an already-handled id is suppressed regardless of the
// dedup window (ack finalize + pump claim, both window-independent).
{
  const queue = createQueue()
  const sink = createSink()
  const clock = makeClock()
  const downstream = []
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 1 }), sink, clock,
    processMessage: (m) => { downstream.push(m.id); return true },
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run(10)
  clock.advance(99999)
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 }) // replay long after the window
  pump.run(10)
  assert.equal(downstream.length, 1, 'G3: replayed id not re-delivered')
  assert.deepEqual(sink.deliveredIds(), ['m1'])
}

// G4: maxAttempts=1 abandons immediately without a retry cycle.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = makeClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 1000 }), sink, clock, maxAttempts: 1,
    processMessage: () => false,
  })
  pump.run(10)
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.deepEqual(queue.pending(), [])
}

// G5: happy path and duplicate-id suppression unchanged.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = makeClock()
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 1000 }), sink, clock,
    processMessage: () => true,
  })
  pump.run(10)
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
  assert.equal(sink.hasDuplicate(), false)
}

console.log('all guarantee scenarios pass')
